const { withGradleProperties } = require('expo/config-plugins');

/**
 * Raises the Gradle daemon's JVM memory limits in android/gradle.properties.
 *
 * The Expo template ships `-Xmx2048m -XX:MaxMetaspaceSize=512m`, and the
 * release build (react-native-screens:lintVitalAnalyzeRelease in particular)
 * exhausts Metaspace with that cap, failing with just "Metaspace". The
 * android/ folder is regenerated by prebuild, so the fix has to live here
 * rather than in the generated file.
 */
const JVM_ARGS = '-Xmx4096m -XX:MaxMetaspaceSize=1024m';

module.exports = function withGradleJvmArgs(config) {
  return withGradleProperties(config, (config) => {
    const props = config.modResults.filter(
      (item) => !(item.type === 'property' && item.key === 'org.gradle.jvmargs'),
    );
    props.push({ type: 'property', key: 'org.gradle.jvmargs', value: JVM_ARGS });
    config.modResults = props;
    return config;
  });
};
